```sql
/* Выбираем названия помещений, вмещающих 500 человек, и террас того же размера */
SELECT "r"."name"
FROM "room" AS "r"
WHERE "r"."size" = 500
  AND (
    LOWER("r"."indoor_outdoor_space") LIKE '%lobby%'
    OR LOWER("r"."indoor_outdoor_space") LIKE '%terrace%'
  );
```

```sql
/* Список всех поваров */
SELECT c."name" AS chef_name
FROM "chefs" c

UNION ALL

/* Серверы, владеющие испанским языком */
SELECT s."name" AS chef_name
FROM "servers" s
WHERE LOWER(s."language") LIKE '%spanish%';
```

```sql
/* Список всех гостевых комнат */
SELECT gr."room"
FROM "guestrooms" gr
UNION ALL
/* Список люксов с кондиционером */
SELECT s."suite_name"
FROM "suites" s
WHERE LOWER(s."amenities") LIKE '%air conditioning%';
```

```sql
/* Находим каналы связи, которые есть у всех представителей службы поддержки */
SELECT c."channel_value"
FROM "channels" c
JOIN "customer_service_representatives_channels" crc ON crc."channel_id" = c."channel_id"
GROUP BY c."channel_id", c."channel_value"
HAVING COUNT(DISTINCT crc."representative_id") = (
    SELECT COUNT(DISTINCT "id") FROM "customer_service_representatives"
);
```

/* Находим вакансию с минимальной зарплатой и выводим её город и название */
SELECT "city", "job"
FROM "jobs"
WHERE "salary" = (SELECT MIN("salary") FROM "jobs")
ORDER BY "city" ASC NULLS FIRST, "job" ASC NULLS FIRST;

